package es.nvislink.core

/**
 * Boundary to the Rust core (`core/crates/nvl-proto`).
 *
 * Phase 2 replaces [FakeNvlCore] with bindings generated by UniFFI from a thin
 * `nvl-ffi` crate. Keep this interface small: messages in, wire bytes out,
 * received bytes in, decoded messages and ACK info out. All protocol logic
 * (codec, crypto, ARQ, lane choice) stays in Rust; nothing here re-implements it.
 */
sealed interface OutMessage {
    data class Text(val text: String) : OutMessage
    data class StatusOk(val lat: Double?, val lon: Double?) : OutMessage
    data class Sos(val lat: Double?, val lon: Double?) : OutMessage
    data object Poll : OutMessage
}

class EncodedFrame(
    val wire: ByteArray,
    val counter: Int,
    val js8Frames: Int,
)

interface NvlCore {
    /** Seal a message. `encrypted = false` is signed plaintext (legal default on air). */
    fun encode(msg: OutMessage, encrypted: Boolean): EncodedFrame
}

/** Stand-in until the Rust core is linked. Produces no real frames. */
class FakeNvlCore : NvlCore {
    private var counter = 0

    override fun encode(msg: OutMessage, encrypted: Boolean): EncodedFrame =
        EncodedFrame(wire = ByteArray(0), counter = counter++, js8Frames = 1)
}
